using System.Diagnostics;using System.Security.Cryptography;using System.Text;
namespace AssetFlow.Agent;
public sealed class UpdateService(AgentClient client,ILogger<UpdateService> log){public async Task CheckAndApply(CancellationToken ct){var release=await client.LatestRelease(ct);if(release is null||!System.Version.TryParse(release.Version,out var latest)||latest<=System.Version.Parse(AgentClient.Version))return;var root=AppContext.BaseDirectory;var updateDir=Path.Combine(root,"updates");Directory.CreateDirectory(updateDir);var pending=Path.Combine(updateDir,$"AssetFlow.Agent-{release.Version}.exe");await client.DownloadRelease(release.Version,pending,ct);await using(var stream=File.OpenRead(pending)){var actual=Convert.ToHexString(await SHA256.HashDataAsync(stream,ct));if(!actual.Equals(release.Sha256,StringComparison.OrdinalIgnoreCase)){File.Delete(pending);throw new InvalidDataException("Downloaded update SHA-256 does not match release metadata.");}}var target=Environment.ProcessPath??Path.Combine(root,"AssetFlow.Agent.exe");var script=Path.Combine(updateDir,"apply-update.cmd");var body=$"@echo off\r\nsetlocal\r\nsc stop AssetFlowAgent >nul 2>&1\r\n:wait\r\ntimeout /t 2 /nobreak >nul\r\ntasklist /FI \"PID eq {Environment.ProcessId}\" | find \"{Environment.ProcessId}\" >nul && goto wait\r\ncopy /Y \"{target}\" \"{target}.bak\" >nul\r\nmove /Y \"{pending}\" \"{target}\" >nul\r\nif errorlevel 1 (copy /Y \"{target}.bak\" \"{target}\" >nul)\r\nsc start AssetFlowAgent >nul 2>&1\r\n";await File.WriteAllTextAsync(script,body,Encoding.ASCII,ct);log.LogInformation("Applying agent update {Current} -> {Latest}",AgentClient.Version,release.Version);Process.Start(new ProcessStartInfo("cmd.exe",$"/c \"{script}\""){UseShellExecute=true,CreateNoWindow=true});}}
